let N = 100 ; let M = 100 ; let RR = 300 ; 

let X[] = new Array(N) ; let Y[] = new Array(N) ;
let R ; let A ; let I ; let II ; let Q ; let QQ ; let P ; let PP ; let S ;

function setup(){
  createCanvas(600, 600) ; background(0) ;
  fill(0,0,0,10) ; stroke(255,0,0) ;
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(-300,+300) ; Y[I] = random(-300,+300) ;
  }//let Q = sqrt(2) ; QQ = RR/Q ; P = -PI/2 ; PP = P+PI ;
}//setup()

function draw(){
  rect(0,0,599,599) ;
  for ( I = 0 ; I < N ; I++ ){
		for ( II = 0 ; II < M ; II++ ){
			if ( X[I] > 0 ){
				A = atan(Y[I]/X[I]) ;
				R = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
				A = A*2 + P ; R = R/Q ;
				X[I] = R*cos(A) - (QQ*cos(S)) ;
				Y[I] = R*sin(A) - (QQ*sin(S)) ;
			}else{
				A = atan(Y[I]/X[I]) ;
				R = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
				A = A*2 + PP ; R = R/Q ;
				X[I] = R*cos(A) + (QQ*cos(S)) ;
				Y[I] = R*sin(A) + (QQ*sin(S)) ;
			}
      point(X[I]+300,Y[I]+300) ; 
		}//II
		if( R > 30000 ){ X[I] = random(-300,+300) ; Y[I] = random(-300,+300) ; }
  }//let P = -PI*float((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/600 ; PP = P+PI ;
	S = -PI*float((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))/600 ;
}//draw()

